// el archivo contiene los bytes 0123456
int a = open("f", O_RDONLY);
int b = dup(a);                 // misma entrada de archivo abierto que a
int c = open("f", O_RDONLY);    // entrada nueva, offset 0
char buf[2], x, y;
read(a, buf, 2);                // buf = '0','1'; el offset compartido ahora es 2
read(b, &x, 1);                 // x = '2', porque el offset es compartido
read(c, &y, 1);                 // y = '0', porque c tiene su propio offset
